ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"query": {
    "aggregate": p('mongo-db-sapi.collections.identity-validation'),
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": {
        	"num_doc": vars.requestOrder.customer.documentNumber,
        	"tipo_doc": vars.requestOrder.customer.documentType,
        	"estado": "VIGENTE"
        }
      }
    ],
    "cursor": {}
  }
}

%dw 2.0 output application/json
var resultBolean = sizeOf(payload filter (e) -> e.isValid == false) > 0
--- { ruleId: p('rules-id.validate-identity'), isValid: if(resultBolean) false else true, detailEvaluated: payload }

%dw 2.0
output application/json
---
{
	ruleId: p('rules-id.validate-identity'),
	isValid: false,
	detailEvaluated: [
		{
	    "evaluateId": "Validacion_Identidad",
	    "isValid": false,
	    "detail": "Cliente no cuenta con una validacion de identidad VIGENTE"
  		}
	]
}
